// Files imported with ?highlight=GRAMMAR (see build/highlight-vite-plugin.ts).
declare module "*?highlight=typescript" {
  const source: import("./_components/highlight").Highlighted;
  export default source;
}
declare module "*?highlight=python" {
  const source: import("./_components/highlight").Highlighted;
  export default source;
}
declare module "*?highlight=toml" {
  const source: import("./_components/highlight").Highlighted;
  export default source;
}
